  "question": {
   "fr": "Que se passe-t-il si j'échoue à un cours ou à un examen ?",
   "en": "What happens if I fail a course or an exam?"
  },
  "answer": {
   "fr": "Échouer un examen ne fait pas automatiquement échouer le cours : tout dépend de la pondération du plan de cours et de la note de passage exigée. Si la note finale est insuffisante, le cours est échoué et il faut généralement le reprendre; en génie, un cours échoué peut bloquer les cours qui en dépendent. Un échec peut aussi affecter la MPC, la probation ou les bourses : parle à ton professeur et à ton unité scolaire dès que la difficulté apparaît, et vérifie les règles de reprise dans la réglementation académique.",
   "en": "Failing one exam does not automatically fail the course: it depends on the syllabus weighting and the passing grade required. If the final grade is too low, the course is failed and usually must be retaken; in engineering a failed course can block the courses that depend on it. A failure can also affect your CGPA, probation status or scholarships: talk to your instructor and academic unit as soon as a problem appears, and check the retake rules in the academic regulations."
  },
