   "fr": "Il faut présenter une demande de report (examen différé) à ta faculté ou à ton unité scolaire dans les jours qui suivent l'absence, avec un justificatif — typiquement un certificat médical ou une preuve de circonstance exceptionnelle. La demande est évaluée selon la réglementation académique, et un report accordé a ses propres dates et parfois des frais administratifs. Ne laisse pas passer le délai : une absence non justifiée mène à la note zéro pour l'évaluation manquée.",
   "en": "You must submit a deferral request to your faculty or academic unit within days of the absence, with supporting documentation — typically a medical certificate or proof of exceptional circumstances. The request is assessed under the academic regulations, and an approved deferral has its own dates and sometimes an administrative fee. Do not miss the window: an unjustified absence results in a zero for the missed assessment."
