   "fr": "La moyenne pondérée cumulative (MPC, ou CGPA) est la moyenne de tes notes, chaque note étant pondérée par les crédits du cours : un cours de 3 crédits pèse moitié moins qu'un cours de 6 crédits. Seules les notes chiffrées entrent dans le calcul, et la conversion lettre-points suit l'échelle officielle de l'Université. Ta MPC à jour, par session et cumulative, est affichée dans uoZone avec ton relevé non officiel.",
   "en": "The cumulative grade point average (CGPA) is the average of your grades, each weighted by the course credits: a 3-credit course counts half as much as a 6-credit course. Only numeric grades enter the calculation, and the letter-to-point conversion follows the University's official scale. Your current term and cumulative GPA are shown in uoZone with your unofficial transcript."
