   "fr": "La démarche commence par une demande de révision auprès du professeur du cours, dans le délai prévu par la réglementation (souvent quelques semaines après la publication de la note), en expliquant précisément ce qui te semble mal évalué. Si le désaccord persiste, un recours formel peut être déposé auprès de la faculté, puis au-delà selon les règles de l'Université. L'ombudsman étudiant peut t'expliquer la procédure et t'aider à préparer le dossier, sans le faire à ta place.",
   "en": "Start with a request for review to the course instructor within the period set by the regulations (often a few weeks after grades are posted), explaining precisely what you believe was misgraded. If the disagreement remains, a formal appeal can go to the faculty and then further under University rules. The student ombudsperson can explain the procedure and help you prepare your case, though not act on your behalf."
