   "en": "You must first apply to graduate in uoZone before the deadline for the target term — for example March 31, 2027 for the spring 2027 convocation. Spring 2027 convocation ceremonies take place June 9 to 13, 2027; the diploma is then issued as the University indicates. Check your file with your academic unit to confirm that all program credits are complete."
