   "en": "UHIP (University Health Insurance Plan) is the mandatory health insurance for international students and their dependants in Ontario: it covers part of medical care while you study. The University enrols eligible students automatically and the premium appears on your student account; the insurance card and coverage details are available from international student services and on the UHIP website. Carry your card for any medical appointment."
