   "en": "Your invoice and balance appear in uoZone under your student account: the University lists the accepted payment methods (online banking, card payment under current rules) and the term deadlines. Pay before the deadline to avoid late interest and a hold on enrolment, transcripts or proof of enrolment. For a receipt, a payment arrangement or a billing error, InfoService (Tabaret, room 129) is the contact point."
