   "en": "The Financial Aid and Awards office is in Desmarais Hall, 55 Laurier Avenue East, room 3156 (loansandawards@uottawa.ca). There is no single deadline: every scholarship has its own, and forms are usually available about two months before it. Some admission scholarships are awarded automatically based on grades, while in-course scholarships and awards require an application; check the official awards directory for the list, criteria and dates."
