   "en": "Submit a written request to your professor or the person designated by your faculty, stating the religious observance and the accommodation you need. For a requirement in the syllabus, it's within two weeks of the start of the course; for one announced later, within five working days; and for a final exam, within five working days of the exam schedule being posted."
