   "en": "Your uOttawa student card is your U-Pass: it gives you unlimited access to OC Transpo buses and trains in Ottawa and STO in Gatineau. Just tap and hold your card on the reader when you board. The U-Pass is mandatory for full-time students and those on a co-op work term; check your U-Pass portal to see if your card is ready."
