  "answer": {
   "fr": "Il y a quatre types de plans : le plan de 7 jours et le plan de 5 jours, qui donnent un accès illimité à la salle à manger, le plan Pay-as-you-go, un solde utilisable à tous les comptoirs du campus, et le plan bloc de 50, 75 ou 100 entrées à la salle à manger. Le plan de 5 jours est obligatoire à Leblanc, Marchand, Stanton, Thompson, Henderson et 90 University, et tu peux passer au plan de 7 jours. Tous les plans sont chargés sur ta carte étudiante uOttawa.",
   "en": "There are four types of plans: the 7-day and 5-day plans, which give unlimited access to the Dining Hall, the Pay-as-you-go plan, a balance you can use at any food location on campus, and the block plan of 50, 75 or 100 Dining Hall entries. The 5-day plan is mandatory at Leblanc, Marchand, Stanton, Thompson, Henderson and 90 University, and you can upgrade to the 7-day plan. All plans are loaded onto your uOttawa student card."
  },
